/**
 * Password entry component.
 * 
 * @see https://github.com/MK-IT/gatsby-theme-password-protect/blob/master/src/components/PasswordProtect.js
 * Write-only the password as cookie
 */
import React, { useState } from 'react';
import { setSessionPassword } from '../helpers/passwordProtectUtils.js';
import useSiteMetaData from "../static_queries/useSiteMetadata";
import { IoMailOutline } from "react-icons/io5";
import { navigate } from '@gatsbyjs/reach-router';
import headerStyles from "../styles/components/header.module.scss";

const styles = {
  wrapper: {
    minHeight: '100vh',
    background: 'radial-gradient(107.81% 212.88% at 0 0, rgba(255, 155, 227, 0.3) 0%, rgba(255, 252, 184, 0.2) 25%, rgba(189, 252, 201, 0.3) 50%, rgba(126, 247, 255, 0.3) 75%, #ffffff 100%)',
    display: 'flex',
    flexDirection: 'column',
    justifyContent: 'center',
    alignItems: 'center',
    padding: '2rem 1.25rem',
    boxSizing: 'border-box'
  },
  headline: {
    textAlign: 'center',
    maxWidth: '520px',
    marginBottom: '2rem',
    whiteSpace: 'pre-line'
  },
  form: {
    width: '380px',
    padding: '16px',
    display: 'flex',
    flexDirection: 'column',
    gap: '12px'
  },
  input: {
    width: '100%',
    height: '48px',
    borderRadius: '16px',
    paddingInline: '24px',
    border: '2px solid #e7e7e7',
    outline: 'none',
    boxSizing: 'border-box',
    fontFamily: 'inherit',
    fontSize: '1rem',
    color: '#111827'
  },
  button: {
    width: '100%',
    height: '48px',
    background: 'black',
    color: '#fff',
    border: '2px solid black',
    borderRadius: '24px',
    fontSize: '20px',
    fontWeight: '400',
    fontFamily: 'sans-serif',
    cursor: 'pointer',
    transition: 'background-color 0.15s ease, border-color 0.15s ease, color 0.15s ease'
  },
  buttonHover: {
    background: '#ffffff',
    color: '#000000',
    borderColor: '#e2e8f0'
  },
  accessRow: {
    display: 'flex',
    alignItems: 'center',
    gap: '8px',
    marginTop: '16px',
    marginBottom: '24px',
    padding: '0 15px'
  },
  accessText: {
    fontSize: '1.125rem',
    color: '#6b7280',
    margin: 0,
    fontWeight: 400
  },
  backContainer: {
    padding: '0 15px'
  }
};

const PasswordProtect = () => {
  const { infoData } = useSiteMetaData();
  const [password, setPassword] = useState('');
  const [isButtonHovered, buttonHover] = useState(false);

  const onSubmit = event => {
    event.preventDefault();
    setSessionPassword(password);
    window.location.reload(); // eslint-disable-line
  };

  return (
    <div style={styles.wrapper}>
      {/* 2-line balanced headline */}
      <h1 style={styles.headline}>
        Enter password to unlock{"\n"}this case study
      </h1>

      <form onSubmit={onSubmit} style={styles.form}>
        <input
          name="password"
          type="password"
          placeholder="Enter password"
          value={password}
          onChange={event => setPassword(event.target.value)}
          style={styles.input}
        />

        <button
          type="submit"
          style={{
            ...styles.button,
            ...(isButtonHovered ? styles.buttonHover : null)
          }}
          onMouseEnter={() => buttonHover(true)}
          onMouseLeave={() => buttonHover(false)}
        >
          Unlock
        </button>
      </form>

      {/* "Need access?" regular text + email pill */}
      <div style={styles.accessRow}>
        <span style={styles.accessText}>Need access?</span>
        <a 
          href={`mailto:${infoData?.contact?.email || 'boyerserpe@gmail.com'}`}
          className="pill-button"
          style={{ marginTop: 0 }}
        >
          <IoMailOutline size={18} />
          <span>Send me an email</span>
        </a>
      </div>

      {/* Back button strictly using headerStyles.back_link */}
      <div style={styles.backContainer}>
        <button 
          className={headerStyles.back_link} 
          onClick={() => navigate(-1)}
          type="button"
        >
          ← Back
        </button>
      </div>
    </div>
  );
};

export default PasswordProtect;